import os

def get_complete_single_copy(filepath):
    """Extract set of BUSCO IDs with Status='Complete' (single-copy)"""
    complete = set()
    with open(filepath) as f:
        for line in f:
            if line.startswith('#'):
                continue
            parts = line.strip().split('\t')
            if len(parts) >= 2:
                busco_id = parts[0]
                status = parts[1]
                if status == 'Complete':
                    complete.add(busco_id)
    return complete

base = '/workspace/busco_outputs'
species = ['Cele', 'Ggal', 'Ncra', 'Scer']

results = {}
for sp in species:
    results[sp] = get_complete_single_copy(f'{base}/{sp}_full_table.tsv')
    print(f"{sp}: {len(results[sp])} complete single-copy BUSCOs")

# Find intersection (present and complete in ALL four)
shared = results['Cele'] & results['Ggal'] & results['Ncra'] & results['Scer']
print(f"\nShared complete single-copy in all 4 proteomes: {len(shared)}")

# Also check pairwise intersections for context
for i, sp1 in enumerate(species):
    for sp2 in species[i+1:]:
        inter = results[sp1] & results[sp2]
        print(f"  {sp1} & {sp2}: {len(inter)}")

# What's the total number of BUSCOs in eukaryota_odb10?
# Count unique BUSCO IDs across all tables
all_ids = set()
for sp in species:
    with open(f'{base}/{sp}_full_table.tsv') as f:
        for line in f:
            if line.startswith('#'):
                continue
            parts = line.strip().split('\t')
            if len(parts) >= 1 and parts[0]:
                all_ids.add(parts[0])
print(f"\nTotal unique BUSCO IDs across all 4: {len(all_ids)}")
