import os

def get_status(filepath, target_id):
    with open(filepath) as f:
        for line in f:
            if line.startswith('#'):
                continue
            parts = line.strip().split('\t')
            if parts[0] == target_id:
                return parts[1]
    return None

def get_complete_set(filepath):
    complete = set()
    with open(filepath) as f:
        for line in f:
            if line.startswith('#'):
                continue
            parts = line.strip().split('\t')
            if len(parts) >= 2 and parts[1] == 'Complete':
                complete.add(parts[0])
    return complete

base = '/workspace/busco_outputs'
